await runScript(async (ctx) => {
    const { bot, sdk } = ctx;
    const state = sdk.getState();
    if (!state) { console.log('NO STATE'); return; }
    console.log('Pos', state.player.worldX, state.player.worldZ, 'HP', state.player.hp + '/' + state.player.maxHp, 'cl', state.player.combatLevel);
    console.log('Skills:', state.skills.map(s => `${s.name}:${s.baseLevel}`).join(' '));
    console.log('Inv:', sdk.getInventory().map(i => i.name).join(', '));
    const npcs = state.nearbyNpcs
        .filter(n => n.optionsWithIndex.some(o => /attack/i.test(o.text)))
        .sort((a, b) => (a.combatLevel * (a.maxHp ?? 0)) - (b.combatLevel * (b.maxHp ?? 0)));
    for (const n of npcs.slice(0, 40)) {
        console.log(`NPC ${n.name} idx${n.index} cl${n.combatLevel} hp${n.maxHp} d${n.distance} reach${n.reachable} inCombat${n.inCombat}`);
    }
    console.log('loc count', state.nearbyLocs.length);
}, { timeout: 30_000 });

