import { runScript } from '../../sdk/runner';

await runScript(async (ctx) => {
    const { bot, sdk } = ctx;
    const log = (...a: any[]) => console.log('[C]', ...a);

    await bot.equipItem(/bronze sword/i);
    await bot.equipItem(/wooden shield/i);
    await bot.walkTo(3150, 3202, 4);
    await sdk.waitForTicks(2);

    const st = sdk.getState();
    if (!st) { log('NO STATE'); return; }
    log('pos', st.player.worldX, st.player.worldZ, 'HP', st.player.hp + '/' + st.player.maxHp, 'tick', st.tick);

    const cand = st.nearbyNpcs
        .filter(n => n.optionsWithIndex.some(o => /attack/i.test(o.text)))
        .filter(n => n.combatLevel >= 3 && n.combatLevel <= 12)
        .sort((a, b) => b.combatLevel - a.combatLevel || a.distance - b.distance);
    for (const n of cand.slice(0, 15)) log(`cand ${n.name} cl${n.combatLevel} hp${n.maxHp} d${n.distance} reach${n.reachable}`);

    const target = cand.find(n => n.reachable !== false) ?? cand[0];
    if (!target) { log('NO TARGET'); return; }
    log('TARGET', target.name, 'cl', target.combatLevel, 'idx', target.index);

    const startTick = sdk.getState()!.tick;
    const start = Date.now();
    let result = await bot.attack(target);
    log('attack result', JSON.stringify(result));

    const targetIdx = target.index;
    const targetName = target.name;
    let lastHp = sdk.getState()!.player.hp;
    const deadline = Date.now() + 180_000;

    while (Date.now() < deadline) {
        await sdk.waitForTicks(1);
        const s = sdk.getState();
        if (!s) continue;
        const p = s.player;
        if (p.hp <= 4) {
            const food = sdk.findInventoryItem(/shrimps|bread/i);
            if (food) { await bot.eatFood(food); log('ate, hp now', sdk.getState()!.player.hp); }
        }
        const still = s.nearbyNpcs.find(n => n.index === targetIdx);
        const sameName = s.nearbyNpcs.find(n => n.name === targetName && n.inCombat && n.targetIndex === p.index);
        if (!still) { log('target gone (dead?) at real+', ((Date.now() - start) / 1000).toFixed(1), 'tick', s.tick); break; }
        if (still.hp !== null && still.hp <= 0) { log('target hp0', s.tick); break; }
        if (!s.player.combat.inCombat && !sameName && !still.inCombat) {
            log('no longer in combat; re-attacking');
            await bot.attack(still);
        }
        if (s.player.hp < lastHp) log('took dmg hp', s.player.hp);
        lastHp = s.player.hp;
    }

    const end = sdk.getState()!;
    const ticks = end.tick - startTick;
    log('END tick', end.tick, 'elapsedTicks', ticks, 'gameSeconds', (ticks * 0.6).toFixed(1), 'realSec', ((Date.now() - start) / 1000).toFixed(1));
    log('xp', end.skills.filter(s => s.experience > 0).map(s => `${s.name}:${s.experience}`).join(' '));
    log('hp', end.player.hp + '/' + end.player.maxHp, 'pos', end.player.worldX, end.player.worldZ);
}, { timeout: 240_000 });

