input.content:
import { runScript } from '../../sdk/runner';

await runScript(async (ctx) => {
    const { bot, sdk } = ctx;
    const log = (...a: any[]) => console.log('[T]', ...a);

    await bot.equipItem(/bronze sword/i);
    await bot.equipItem(/wooden shield/i);

    const realDeadline = Date.now() + 78_000;
    let kills = 0;

    while (Date.now() < realDeadline) {
        const st = sdk.getState();
        if (!st) { await sdk.waitForTicks(1); continue; }
        const p = st.player;
        if (p.hp <= 4) {
            const food = sdk.findInventoryItem(/shrimps|bread/i);
            if (food) { await bot.eatFood(food); }
        }
        const cand = st.nearbyNpcs
            .filter(n => n.optionsWithIndex.some(o => /attack/i.test(o.text)))
            .filter(n => n.combatLevel >= 3 && n.combatLevel <= 10)
            .filter(n => n.reachable !== false && !n.inCombat)
            .sort((a, b) => b.combatLevel - a.combatLevel || a.distance - b.distance);
        const target = cand[0];
        if (!target) {
            await bot.walkTo(3176, 3206, 6);
            await sdk.waitForTicks(3);
            continue;
        }
        const startTick = sdk.getState()!.tick;
        const idx = target.index;
        try { await bot.attack(target); } catch { }
        const tDeadline = Date.now() + 30_000;
        while (Date.now() < tDeadline && Date.now() < realDeadline) {
            await sdk.waitForTicks(1);
            const s = sdk.getState();
            if (!s) continue;
            if (s.player.hp <= 4) {
                const food = sdk.findInventoryItem(/shrimps|bread/i);
                if (food) { await bot.eatFood(food); }
            }
            const still = s.nearbyNpcs.find(n => n.index === idx);
            if (!still) break;
            if (still.hp !== null && still.hp <= 0) break;
            if (!s.player.combat.inCombat && !still.inCombat) { try { await bot.attack(still); } catch { } }
        }
        const end = sdk.getState()!;
        kills++;
        log(`kill#${kills} ${target.name} cl${target.combatLevel} ttkTicks=${end.tick - startTick} hp=${end.player.hp}/${end.player.maxHp} atk=${end.skills.find(s => s.name === 'Attack')?.baseLevel} str=${end.skills.find(s => s.name === 'Strength')?.baseLevel}`);
    }
    const end = sdk.getState()!;
    log('DONE kills', kills, 'pos', end.player.worldX, end.player.worldZ);
    log('skills', end.skills.filter(s => s.experience > 0).map(s => `${s.name}:${s.baseLevel}(${s.experience})`).join(' '));
}, { timeout: 120_000 });

